package cn.musecanvas.api;

import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;

class ReviewerCredentialsTest {
    // Public, non-deployment fixture generated by scripts/init-reviewer.mjs.
    static final String HASH="pbkdf2-sha256$600000$07070707070707070707070707070707$6954d4868e2b62677ad43e12a35536bc29cb666d5c0347759686b106d460e0a4";
    @Test void nodeGeneratedHashesVerifyWithoutStoringAPlaintextPassword() {
        assertTrue(ReviewerCredentials.matches("reviewer-unit-test-password",HASH));
        assertFalse(ReviewerCredentials.matches("wrong-password",HASH));
        assertFalse(ReviewerCredentials.matches(null,HASH));
        assertFalse(ReviewerCredentials.matches("",HASH));
        assertFalse(ReviewerCredentials.matches("x".repeat(257),HASH));
    }
    @Test void malformedOrUnboundedHashesCannotTriggerAnExpensiveDerivation() {
        for(String value:new String[]{"",HASH.replace("600000","1"),HASH.replace("600000","999999999"),HASH+"suffix",HASH.replace("pbkdf2-sha256","unknown"),"plain-password"}) {
            assertFalse(ReviewerCredentials.validHash(value));
            assertFalse(ReviewerCredentials.matches("any",value));
        }
    }
}
